{
  "name": "哈佛注射泵（Pump 11/PHD2000）",
  "name_en": "Harvard syringe pump (Pump 11/PHD2000)",
  "manufacturer": "Harvard Apparatus",
  "description": "用于精密液体输送的注射泵，可通过串口按地址控制单台或串接泵，设置注射器直径、流速和目标体积，并执行注液、回抽与停止操作，适用于微流控、定量加液和连续流实验。",
  "description_en": "A precision syringe pump for liquid delivery, controllable over a serial connection with pump addressing on a daisy chain. It supports setting syringe diameter, flow rate, and target volume, and performing infusion, withdrawal, and stop operations for microfluidics, metered dispensing, and flow experiments.",
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向注射泵发送原始串口命令。",
      "description_en": "Send a raw serial command to the syringe pump."
    },
    {
      "action_name": "auto-read",
      "description": "读取注射泵的串口响应。",
      "description_en": "Read the serial response from the syringe pump."
    },
    {
      "action_name": "auto-setdiameter",
      "description": "设置注射器直径（毫米）。",
      "description_en": "Set the syringe diameter in millimetres."
    },
    {
      "action_name": "auto-setflowrate",
      "description": "设置流速（微升/分钟）。",
      "description_en": "Set the flow rate in microlitres per minute."
    },
    {
      "action_name": "auto-infuse",
      "description": "启动注液。",
      "description_en": "Start infusion."
    },
    {
      "action_name": "auto-withdraw",
      "description": "启动回抽。",
      "description_en": "Start withdrawal."
    },
    {
      "action_name": "auto-stop",
      "description": "停止泵运行。",
      "description_en": "Stop the pump."
    },
    {
      "action_name": "auto-settargetvolume",
      "description": "设置目标体积（微升）。",
      "description_en": "Set the target volume in microlitres."
    },
    {
      "action_name": "auto-waituntiltarget",
      "description": "等待泵达到目标体积。",
      "description_en": "Wait until the pump reaches the target volume."
    }
  ],
  "tag_hints": [
    "syringe pump",
    "infusion",
    "withdrawal",
    "flow rate control",
    "target volume dosing",
    "serial control",
    "Harvard Pump 11",
    "microfluidics"
  ]
}

